import {deleteCookie} from '@github-ui/cookies'
import {COOKIE_NAME} from '@github-ui/global-sso-banner/constants'
import {KebabHorizontalIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import React from 'react'

interface SettingsMenuProps {
  onCookieReset?: () => void
}

export function SettingsMenu({onCookieReset}: SettingsMenuProps) {
  const [isCookieResetDialogOpen, setIsCookieResetDialogOpen] = React.useState(false)

  const confirmCookieReset = () => {
    deleteCookie(COOKIE_NAME)
    setIsCookieResetDialogOpen(false)
    onCookieReset?.()
  }

  return (
    <>
      <ActionMenu>
        <ActionMenu.Anchor>
          <IconButton aria-label="SSO banner settings" icon={KebabHorizontalIcon} size="small" tooltipDirection="w" />
        </ActionMenu.Anchor>

        <ActionMenu.Overlay side="outside-bottom" align="end">
          <ActionList>
            <ActionList.Item onSelect={() => setIsCookieResetDialogOpen(true)}>Reset SSO banner</ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>

      {isCookieResetDialogOpen && (
        <Dialog
          title="Reset SSO Banner"
          width="medium"
          height="auto"
          onClose={() => setIsCookieResetDialogOpen(false)}
          footerButtons={[
            {buttonType: 'default', content: 'Cancel', onClick: () => setIsCookieResetDialogOpen(false)},
            {
              buttonType: 'primary',
              content: 'Reset SSO banner',
              onClick: confirmCookieReset,
            },
          ]}
        >
          <p>Are you sure you want to reset your dismissal of the single sign-on banner on this device?</p>
          <p>
            This will clear your dismissal preferences and the SSO banner may appear again for organizations that
            require single sign-on authentication.
          </p>
        </Dialog>
      )}
    </>
  )
}
